    const size_t partial_capacity = (static_cast<size_t>(n) - 1u) / 128u + 1u;
    long long *partial_a = nullptr;
    long long *partial_b = nullptr;
    if (n > 128) {
        partial_a = static_cast<long long *>(scratch);
