        if (blocks == 1) {
            int *destination;
            if (input_is_wide) {
                long long *wide_destination = next_is_a ? partial_a : partial_b;
                destination = reinterpret_cast<int *>(wide_destination);
                reduce0<long long, int><<<blocks, 128>>>(
